    index[user_id]["total"] += amount


def build_user_purchase_index(
    events: list[dict],
    *,
    min_amount: int = 0,
) -> dict[str, dict[str, int]]:
    # Input validation
    if not isinstance(events, list):
        raise TypeError(f"events must be a list, got {type(events).__name__}")
    if not isinstance(min_amount, int):
        raise TypeError(f"min_amount must be an int, got {type(min_amount).__name__}")
    if min_amount < 0:
        raise ValueError("min_amount must be non-negative")

    for i, event in enumerate(events):
        if not isinstance(event, dict):
            raise TypeError(
                f"Each event must be a dict, got {type(event).__name__} at index {i}"
            )

    index: dict[str, dict[str, int]] = {}

    for event in events:
        if not _is_valid_purchase(event, min_amount):
            continue
        _accumulate(index, event["user_id"], event["amount"])

    return index

